// RAG ve Vektör Veritabanı cheat sheet. 11 konu; Python örnekli.
import type { Topic } from './types'

export const ragGiris: { q: string; a: string }[] = [
  { q: 'RAG ne demek?', a: 'Retrieval-Augmented Generation, Türkçesiyle "bulup getirerek üretme". Fikir basit: modele soruyu sormadan önce kendi belgelerinden soruyla ilgili parçaları bulur, bunları promptun içine koyar ve "bu belgelere dayanarak cevapla" dersin. Model artık senin PDF\'lerin, şirket wikin ya da ürün kılavuzunla cevap verir ve kaynağını gösterir.' },
  { q: 'Model zaten her şeyi bilmiyor mu, neden belge vereyim?', a: 'Model, eğitim verisindeki genel bilgiyi bilir; senin sözleşmeni, dünkü toplantı notunu, şirket iade politikanı bilmez. Sorarsan uydurur. Bağlam penceresi de sınırlı olduğu için bin belgeyi tek seferde veremezsin. RAG, her soruda sadece ilgili üç beş parçayı bulup verir; hem uydurma azalır hem maliyet düşer.' },
  { q: 'Belgeyi prompta yapıştırsam olmaz mı?', a: 'Az sayıda belge için olur ve en basit yoldur: birkaç PDF modern modellerin bağlam penceresine sığar, önbellekle de ucuzlar. Sorun yüzlerce belgede başlar: hem sığmaz hem her soruda hepsini göndermek pahalıdır. RAG o noktada devreye girer. Bu bölümde "ne zaman RAG, ne zaman doğrudan bağlam" ayrıca anlatılıyor.' },
  { q: 'Embedding ne demek, neden RAG\'in kalbi?', a: 'Embedding, bir metni anlamını taşıyan uzun bir sayı listesine (vektör) çevirmektir. Anlamca yakın metinler yakın sayılar alır: "ucuz uçuş" ile "ekonomik bilet" yakındır, "ucuz uçuş" ile "kedi maması" uzaktır. Böylece "bu soruya en benzeyen belge parçası hangisi" sorusu bir mesafe hesabına dönüşür ve bilgisayar milisaniyede bulur.' },
  { q: 'Vektör veritabanı nedir?', a: 'Bu sayı listelerini saklayan ve "şu vektöre en yakın beş vektörü getir" sorusuna çok hızlı cevap veren depo. Chroma (bilgisayarında, basit), pgvector (Postgres\'in içinde), Qdrant ve Pinecone (büyük ölçek) yaygın seçenekler. Küçük projede Chroma ile başlarsın; zaten Postgres kullanıyorsan pgvector yeter.' },
  { q: 'Parçalama (chunking) ne, neden gerekli?', a: 'Elli sayfalık belgeyi tek vektöre çevirirsen anlam bulanıklaşır; aradığın paragraf kaybolur. Bu yüzden belge 300-800 kelimelik parçalara bölünür ve her parça ayrı embedding alır. Nasıl böldüğün, arama kalitesini en çok etkileyen kararlardan biridir; bu yüzden bölümde ayrı bir konu.' },
  { q: 'Akış baştan sona nasıl?', a: 'İki aşama var. Hazırlık (bir kez): belgeleri oku, parçala, her parçayı embedding\'e çevir, vektör veritabanına kaydet. Sorgu (her soruda): soruyu embedding\'e çevir, en yakın parçaları bul, bunları promptun içine koy, modele sor, cevabı kaynaklarıyla göster. Basit sürümü elli satır koddur.' },
  { q: 'Fine-tuning ile farkı ne?', a: 'Fine-tuning modelin davranışını değiştirir (üslup, biçim); bilgi öğretmek için uygun değildir ve belge değişince yeniden eğitim gerekir. RAG bilgiyi dışarıda tutar: belgeyi güncellersin, anında yeni cevap. Bilgi sorunu için RAG, davranış sorunu için fine-tuning; çoğu zaman sadece RAG yeter.' },
  { q: 'Zor kısmı ne?', a: 'Çalışan sürümü yapmak kolay; iyi çalışan sürümü yapmak zor. Model yanlış cevap veriyorsa genelde arama doğru parçayı bulamamıştır. Parça boyutu, embedding modeli, hibrit arama, yeniden sıralama ve değerlendirme konuları bu yüzden var. Önce basit kur, sonra ölçerek iyileştir.' },
  { q: 'Ön koşul ne?', a: 'LLM API başlığı (model çağırmayı biliyorsun), temel Python ve biraz SQL. Kavramlar Temeller\'de geçti: embedding, token, bağlam penceresi. Pandas bilgisi veri hazırlığında yardımcı olur ama şart değil.' },
  { q: 'Hangi sırayla ilerlemeli?', a: 'Soldaki sıra: Embedding → Belge Yükleme ve Parçalama → Vektör Veritabanı → Temel RAG (ilk çalışan sürüm) → Arama Kalitesi → Çerçeveler → Değerlendirme → İleri Teknikler → Üretim. İlk dört konu ile "PDF\'lerimle sohbet" uygulaması çıkar; gerisi onu iyileştirir.' },
  { q: 'Bu bölümden sonra?', a: 'AI Agent\'lar: arama, ajanın elindeki araçlardan biri olur. Model gerekirse birkaç kez arar, sonucu değerlendirir, başka kaynağa bakar. RAG\'i anlamadan ajan kurmak zordur; bu yüzden sıra böyle.' },
]

